const ALIASES = {"compass": "explore", "back": "arrow_back", "arrow": "arrow_forward", "chip": "memory", "voice": "graphic_eq", "copy": "content_copy", "globe": "public", "settings": "tune", "server": "dns", "spark": "auto_awesome"};

/** Render a trusted, decorative SVG without a font or network request.
 * @param {string} name Bundled semantic icon name. @returns {string} SVG markup.
 */
export function icon(name) {
  const key = Object.hasOwn(ALIASES,name) ? ALIASES[name] : name;
  if (!Object.hasOwn(ICONS,key)) throw new RangeError("Unknown interface icon");
  const asset = ICONS[key];
  return `<svg class="ui-icon" viewBox="${asset.viewBox}" aria-hidden="true" focusable="false">${asset.markup}</svg>`;
}

/** Render existing hardware artwork as a decorative icon beside a device name.
 * @param {string} device Setup device identifier. @returns {string} Trusted markup.
 */
export function deviceIcon(device) {
  const hardware = {pi:'pi',mark1:'mark1',mark2:'mark2',devkit:'devkit',jetson:'jetson'};
  if (Object.hasOwn(hardware,device)) {
    return `<span class="device-symbol" aria-hidden="true"><img src="./assets/hardware-${hardware[device]}.png" alt="" width="56" height="56"></span>`;
  }
  if (['computer','mac','windows','server'].includes(device)) {
    return `<span class="device-symbol device-symbol-sprite${device==='server'?' device-symbol-server':''}" aria-hidden="true"></span>`;
  }
  return `<span class="device-symbol" aria-hidden="true">${icon('chip')}</span>`;
}
